const next = cloneBadges(stable), actual = badgeView(cp);
for (const player of first.players) {
  const current = next.get(player.id)!, original = { ...current };
  const wasAlive = previousCheckpoint.players.find(p => p.id === player.id)?.alive;
  // assign 只遍历活人。前一 CP 已知死亡席位跳过，不把旧徽一起改成新配置。
  if (wasAlive === false) {
    if (!equal(current, actual.get(player.id))) break;
    continue;
  }
  // 本段来源只是提案，无物理提交游标时保留写／跳过；二者不变成任意字段豁免。
  const maySkip = wasAlive === undefined || e.episodes.some(episode =>
    episode.actorId === player.id && episode.start >= previousCheckpoint.eventCount && episode.start < cp.eventCount);
  current.isSheriff = player.id === id; result.push(cloneBadges(next));
  current.destroyed = false; result.push(cloneBadges(next));
  current.voteWeight = weight; result.push(cloneBadges(next));
  if (policy === "awa_holder_choice_v1") current.handoffPolicy = policy; else delete current.handoffPolicy;
  result.push(cloneBadges(next));
  if (current.canVote) { current.rightWeight = player.id === id ? weight : 1; result.push(cloneBadges(next)); }
  // 每席随后不再被本命令写。只推进与实际末 CP 相符的整席分支，避免未知席位的2^N组合。
  if (!equal(current, actual.get(player.id))) {
    if (maySkip && equal(original, actual.get(player.id))) next.set(player.id, original);
    else break;
  }
}

